import{_ as n,a0 as s,w as p,s as h,ao as o,I as t,x as r,a1 as i,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const c=JSON.parse('{"title":"Python 中可觀測性的 7 個關鍵部分 | LCTT x X-CMD","titleTemplate":false,"description":"Python 中可觀測性的 7 個關鍵部分 | LCTT (202208) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Python 中可觀測性的 7 個關鍵部分 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Python 中可觀測性的 7 個關鍵部分 | LCTT (202208) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202208/20211122 7 key components of observability in Python","title":"Python 中可觀測性的 7 個關鍵部分","tag":"202208","desc":""},"relativePath":"202208/20211122 7 key components of observability in Python.md","filePath":"[post].md"}'),d={name:"202208/20211122 7 key components of observability in Python.md"};function u(b,e,y,m,P,f){const a=s("Link");return p(),h("div",null,[e[21]||(e[21]=o(`<h1 id="python-中可觀測性的-7-個關鍵部分" tabindex="-1">Python 中可觀測性的 7 個關鍵部分 <a class="header-anchor" href="#python-中可觀測性的-7-個關鍵部分" aria-label="Permalink to “Python 中可觀測性的 7 個關鍵部分”">​</a></h1><blockquote><p>學習為什麼 Python 中的可觀測性很重要，以及如何在你的軟件開發生命週期中實現它。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202208/02/115713cbml51nooltb21bx.jpg" alt=""></p><p>你寫的應用會執行很多代碼，而且是以一種基本上看不到的方式執行。所以你是怎麼知道：</p><ul><li>代碼是否在運行？</li><li>是不是在正常工作？</li><li>誰在使用它，如何使用？</li></ul><p>可觀測性是一種能力，可以通過查看數據來告訴你，你的代碼在做什麼。在這篇文章中，主要關注的問題是分佈式系統中的服務器代碼。並不是説客户端應用代碼的可觀測性不重要，只是説客户端往往不是用 Python 寫的。也不是説可觀測性對數據科學不重要，而是在數據科學領域的可觀測性工具（大多是 Juptyter 和快速反饋）是不同的。</p><h3 id="為什麼可觀測性很重要" tabindex="-1">為什麼可觀測性很重要 <a class="header-anchor" href="#為什麼可觀測性很重要" aria-label="Permalink to “為什麼可觀測性很重要”">​</a></h3><p>所以，為什麼可觀測性重要呢？在軟件開發生命週期（SDLC）中，可觀測性是一個關鍵的部分。</p><p>交付一個應用不是結束，這只是一個新週期的開始。在這個週期中，第一個階段是確認這個新版本運行正常。否則的話，很有可能需要回滾。哪些功能正常運行？哪些功能有細微的錯誤？你需要知道發生了什麼，才能知道接下來要怎麼做。這些東西有時候會以奇怪的方式不能正常運行。不管是天災，還是底層基礎設施的問題，或者應用進入了一種奇怪的狀態，這些東西可能在任何時間以任何理由停止工作。</p><p>在標準 SDLC 之外，你需要知道一切都在運行中。如果沒有，有辦法知道是怎麼不能運行的，這是非常關鍵的。</p><h3 id="反饋" tabindex="-1">反饋 <a class="header-anchor" href="#反饋" aria-label="Permalink to “反饋”">​</a></h3><p>可觀測性的第一部分是獲得反饋。當代碼給出它正在做什麼的信息時，反饋可以在很多方面提供幫助。在模擬環境或測試環境中，反饋有助於發現問題，更重要的是，以更快的方式對它們進行分類。這可以改善在驗證步驟中的工具和交流。</p><p>當進行<ruby>金絲雀部署<rt>canary deployment</rt></ruby>或更改特性標誌時，你需要知道是否要繼續，還是等更長時間，或者回滾，反饋就顯得很重要了。</p><h3 id="監控" tabindex="-1">監控 <a class="header-anchor" href="#監控" aria-label="Permalink to “監控”">​</a></h3><p>有時候你懷疑有些東西不太對。也許是一個依賴服務有問題，或者是社交網站爆出了大量你的網站的問題。也許在相關的系統中有複雜的操作，然後你想確保你的系統能完美處理。在這些情況下，你就想把可觀測性系統的數據整合到控制面板上。</p><p>當寫一個應用的時候，這些控制面板需要是設計標準的一部分。只有當你的應用能把數據共享給這些控制面板，它們才會把這些數據顯示出來。</p><h3 id="警報" tabindex="-1">警報 <a class="header-anchor" href="#警報" aria-label="Permalink to “警報”">​</a></h3><p>看控制面板超過 15 分鐘就像看着油漆變幹一樣。任何人都不應該遭受這種折磨。對於這種任務，我們要有報警系統。報警系統將可觀測性數據與預期數據進行對比，當它們不匹配的時候就發出通知。完全深入研究時間管理超出了本文的範圍。然而，從兩方面來説，可觀測應用是<ruby>報警友好的<rt>alert-friendly</rt></ruby>：</p><ul><li>它們有足夠多，足夠好的數據，發出的警報才是高質量的。</li><li>警報有足夠的數據，或者接收者可以很容易的得到數據，這樣有助於找到源頭。</li></ul><p>高質量警報有三個特點：</p><ul><li>較少的錯報：如果有警報，那一定是有問題了。</li><li>較少的漏報：如果有問題，那一定有警報觸發。</li><li>及時性：警報會迅速發出以減少恢復時間。</li></ul><p>這三個特點是互相有衝突的。你可以通過提高監測的標準來減少錯誤警報，代價是增加了漏報。你也可以通過降低監測的門檻來減少漏報，代價是增加錯報。通過收集更多數據，你也可以同時減少錯報和漏報，而代價是降低了及時性。</p><p>同時改善這三個參數就更難了。這就要求高質量的可觀測性數據。更高質量的數據可以同時改善這三個特點。</p><h3 id="日誌" tabindex="-1">日誌 <a class="header-anchor" href="#日誌" aria-label="Permalink to “日誌”">​</a></h3><p>有的人喜歡嘲笑用打印來調試的方法。但是，在一個大多數軟件都不在你本機運行的世界裏，你所能做的只有打印調試。日誌記錄就是打印調試的一種形式。儘管它有很多缺點，但 Python 日誌庫提供了標準化的日誌記錄。更重要的是，它意味着你可以通過這些庫去記錄日誌。</p><p>應用程序要負責配置日誌的記錄方式。諷刺地是，在應用程序對配置日誌負責了多年以後，現在越來越不是這樣了。在現代容器<ruby>編排<rt>orchestration</rt></ruby>環境中，現代應用程序記錄標準錯誤和標準輸出，並且信任<ruby>編排<rt>orchestration</rt></ruby>系統可以合理的處理日誌。</p><p>然而，你不應該依賴庫，或者説，其他任何地方。如果你想讓操作的人知道發生了什麼，<em>使用日誌，而不是打印</em>。</p><h4 id="日誌級別" tabindex="-1">日誌級別 <a class="header-anchor" href="#日誌級別" aria-label="Permalink to “日誌級別”">​</a></h4><p>日誌記錄的一個最重要功能就是 <em>日誌級別</em>。不同的日誌級別可以讓你合理的過濾並分流日誌。但是這隻有在日誌級別保持一致的情況下才能做到。最後，你應該在整個應用程序中保持日誌級別的一致性。</p><p>選擇不兼容語義的庫可以通過在應用層面的適當配置來追溯修復，這隻需要通過使用 Python 中最重要的通用風格做到：<code>getLogger(__name-_)</code>。</p><p>大多數合理的庫都會遵循這個約定。<ruby>過濾器<rt>Filters</rt></ruby>可以在日誌對象發出之前就地修改它們。你可以給處理程序附加一個過濾器，這個處理程序會根據名稱修改消息，使其具有合適的級別。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import logging</span></span>
<span class="line"><span>LOGGER=logging.getLogger(__name__)</span></span></code></pre></div><p>考慮到這一點，你現在必須明確日誌級別的語義。這其中有很多選項，但是下面這些是我的最愛：</p><ul><li><code>Error</code>：發送一個即時警告。應用程序處於一個需要操作人員引起注意的狀態。（這意味着包含 <code>Critical</code> 和 <code>Error</code>）</li><li><code>Warning</code>：我喜歡把這些稱作“工作時間警報”。這種情況下，應該有人在一個工作日內關注一下。</li><li><code>Info</code>：這是在正常工作流程中發出的。如果懷疑有問題的時候，這個是用來幫助人們瞭解應用程序在做什麼的。</li><li><code>Debug</code>：默認情況下，這個不應該在生產環境中出現。在模擬環境或開發環境下，可以發出來，也可以不發。如果需要更多的信息，在生產環境也可以特地被打開。</li></ul><p>任何情況下都不要在日誌中包含<ruby>個人身份信息<rt>Personal Identifiable Information</rt></ruby>（PII）或密碼。無論日誌級別是什麼，都是如此，比如級別更改，激活調試級別等等。日誌聚合系統很少是 <ruby>PII 安全<rt>PII-safe</rt></ruby>的，特別是隨着 PII 法規的不斷發展（HIPAA、GDPR 等等）。</p><h4 id="日誌聚合" tabindex="-1">日誌聚合 <a class="header-anchor" href="#日誌聚合" aria-label="Permalink to “日誌聚合”">​</a></h4><p>現代系統幾乎都是分佈式的。<ruby>冗餘<rt>redundancy</rt></ruby>、<ruby>擴展性<rt>scaling</rt></ruby>，有時是<ruby>管轄權<rt>jurisdictional</rt></ruby>需要更多的水平分佈。微服務意味着垂直分佈。登錄到每個機器去查看日誌已經是不現實的了。出於合理的控制原因，允許開發人員登錄到機器中會給予他們更多的權限，這不是個好主意。</p><p>所有的日誌都應該被髮到一個聚合器。有一些商業的方案，你可以配置一個 ELK 棧，或者也可以使用其他的資料庫（SQL 或則 no-SQL）。作為一個真正的低技術解決方案，你可以將日誌寫入文件，然後將它們發送到對象存儲中。有很多解決方案，但是最重要的事情是選擇一個，並且將所有東西聚合到一起。</p><h4 id="記錄查詢" tabindex="-1">記錄查詢 <a class="header-anchor" href="#記錄查詢" aria-label="Permalink to “記錄查詢”">​</a></h4><p>在將所有東西記錄到一個地方後，會有很多日誌。具體的聚合器可以定義如何寫查詢，但是無論是通過從存儲中搜索還是寫 NoSQL 查詢，記錄查詢以匹配源和細節都是很有用的。</p><h3 id="指標抓取" tabindex="-1">指標抓取 <a class="header-anchor" href="#指標抓取" aria-label="Permalink to “指標抓取”">​</a></h3><p><ruby>指標抓取<rt>Metric Scraping</rt></ruby>是一個<ruby>服務器拉取<rt>server pull</rt></ruby>模型。指標服務器定時和應用程序連接，並且拉取指標。</p><p>最後，這意味着服務器需要連接和找到所有相關的應用服務器。</p><h4 id="以-prometheus-為標準" tabindex="-1">以 Prometheus 為標準 <a class="header-anchor" href="#以-prometheus-為標準" aria-label="Permalink to “以 Prometheus 為標準”">​</a></h4>`,44)),t("p",null,[e[1]||(e[1]=r("如果你的指標聚合器是 Prometheus，那麼 ",-1)),i(a,{href:"https://opensource.com/article/21/7/run-prometheus-home-container"},{default:l(()=>[...e[0]||(e[0]=[r("Prometheus",-1)])]),_:1}),e[2]||(e[2]=r(" 格式做為一個",-1)),e[3]||(e[3]=t("ruby",null,[r("端點"),t("rt",null,"endpoint")],-1)),e[4]||(e[4]=r("是很有用的。但是，即使聚合器不是 Prometheus，也是很有用的。幾乎所有的系統都包含與 Prometheus 端點兼容的",-1)),e[5]||(e[5]=t("ruby",null,[r("墊片"),t("rt",null,"shim")],-1))]),e[22]||(e[22]=o('<p>使用客户端 Python 庫給你的應用程序加一個 Prometheus 墊片，這將使它能夠被大多數的指標聚合器所抓取。當 Prometheus 發現一個服務器，它就期望找到一個指標端點。這經常是應用程序路由的一部分，通常在 <code>/metrics</code> 路徑下。不管 Web 應用的平台是什麼，如果你能在一個端點下運行一個定製類型的定製字節流，Prometheus 就可以將它抓取。</p><p>對於大多數流行的框架，總有一箇中間件插件或者類似的東西收集指標，如延遲和錯誤率。通常這還不夠。你需要收集定製的應用數據：比如，每個端點的緩存<ruby>命中/缺失<rt>hit/miss</rt></ruby>率，資料庫延遲，等等。</p><h4 id="使用計數器" tabindex="-1">使用計數器 <a class="header-anchor" href="#使用計數器" aria-label="Permalink to “使用計數器”">​</a></h4><p>Prometheus 支持多個數據類型。一個重要且巧妙的類型就是計數器。計數器總是在前進 —— 但有一點需要注意。</p><p>當應用重置，計數器會歸零。計數器中的這些“<ruby>歷時<rt>epochs</rt></ruby>”通過將計數器“創建時間”作為元數據發送來管理。Prometheus 知道不去比較兩個不同<ruby>歷時<rt>epochs</rt></ruby>的計數器。</p><h4 id="使用儀表值" tabindex="-1">使用儀表值 <a class="header-anchor" href="#使用儀表值" aria-label="Permalink to “使用儀表值”">​</a></h4><p>儀表值會簡單很多：它們測量瞬時值。用它們來測量會上下起伏的數據：比如，分配的總內存大小，緩存大小，等等。</p><h4 id="使用枚舉值" tabindex="-1">使用枚舉值 <a class="header-anchor" href="#使用枚舉值" aria-label="Permalink to “使用枚舉值”">​</a></h4><p>枚舉值對於整個應用程序的狀態是很有用的，儘管它們可以以更精細的方式被收集。比如，你正使用一個<ruby>功能門控<rt>feature-gating</rt></ruby>框架，一個有多個狀態（比如，使用中、關閉、<ruby>屏蔽<rt>shadowing</rt></ruby> 等）的功能，也許使用枚舉會更有用。</p><h3 id="分析" tabindex="-1">分析 <a class="header-anchor" href="#分析" aria-label="Permalink to “分析”">​</a></h3><p>分析不同於指標，因為它們要對應連續的事件。比如，在網絡服務器中，事件是一個外部請求及其產生的工作。特別是，在事件完成之前事件分析是不能被髮送的。</p><p>事件包含特定的指標：延遲，數量，以及可能產生的對其他服務請求的細節，等等。</p><h4 id="結構化日誌" tabindex="-1">結構化日誌 <a class="header-anchor" href="#結構化日誌" aria-label="Permalink to “結構化日誌”">​</a></h4><p>現在一個可能的選擇是將日誌結構化。發送事件只發送帶有正確格式的有效<ruby>載荷<rt>payload</rt></ruby>的日誌。這個數據可以從日誌聚合器請求，然後解析，並且放入一個合適的系統，這樣可以對它的可見性。</p><h3 id="錯誤追蹤" tabindex="-1">錯誤追蹤 <a class="header-anchor" href="#錯誤追蹤" aria-label="Permalink to “錯誤追蹤”">​</a></h3><p>你可以使用日誌來追蹤錯誤，也可以用分析來追蹤錯誤。但是一個專門的錯誤系統還是值得的。一個為錯誤而優化的系統可以發送更多的錯誤，因為錯誤畢竟還是罕見的。這樣它就可以發送正確的數據，並且用這些數據，它能做更多智能的事情。Python 中的錯誤追蹤系統通常和一般的異常處理關聯，然後收集數據，並且把它發到一個專門的錯誤聚合器。</p><h4 id="使用-sentry" tabindex="-1">使用 Sentry <a class="header-anchor" href="#使用-sentry" aria-label="Permalink to “使用 Sentry”">​</a></h4><p>很多情況下，自己運行 Sentry 是正確的做法。當錯誤發生時，就説明有些東西就出問題了。可靠地刪除敏感數據是不可能的，因為一定有會出現敏感數據被髮送到不應該的地方。</p><p>通常，這種工作量並不會很大：異常並不常出現。最後，這個系統並不需要很高的質量，也不需要高可靠性的備份。昨天的錯誤應該已經修復了，希望如此，如果沒有，你還會發現的！</p><h3 id="快速、安全、可重複-三者都要" tabindex="-1">快速、安全、可重複：三者都要 <a class="header-anchor" href="#快速、安全、可重複-三者都要" aria-label="Permalink to “快速、安全、可重複：三者都要”">​</a></h3><p>可觀測的系統開發起來更快，因為它們可以給你提供反饋。它們運行起來也更安全，因為當出問題的時候，它們也會更早的讓你知道。最後，因為有反饋迴路，可觀測性也有助於圍繞它構建可重複的過程。可觀測性可以讓你瞭解你的應用程序。而更瞭解它們，就勝利了一半。</p><h4 id="磨刀不誤砍柴功" tabindex="-1">磨刀不誤砍柴功 <a class="header-anchor" href="#磨刀不誤砍柴功" aria-label="Permalink to “磨刀不誤砍柴功”">​</a></h4><p>構建所有的可觀測層是一件困難的事情。總會讓人感覺是在浪費的工作，或者更像是“可以有，但是不急”。</p><p>之後再做這個可以嗎？也許吧，但是不應該。正確的構建可觀測性可以加速後面所有階段的開發：測試、監控，甚至是培訓新人。在一個和科技行業一樣動盪的行業，減少培訓新人的工作量絕對是值得的。</p><p>事實上，可觀測性很重要，所以儘早把它寫出來，然後就可以在整個過程中進行維護。反過來，它也會幫你維護你的軟件。</p><hr>',26)),t("p",null,[e[7]||(e[7]=r("via: ",-1)),i(a,{href:"https://opensource.com/article/21/11/observability-python"},{default:l(()=>[...e[6]||(e[6]=[r("https://opensource.com/article/21/11/observability-python",-1)])]),_:1})]),t("p",null,[e[12]||(e[12]=r("作者：",-1)),i(a,{href:"https://opensource.com/users/moshez"},{default:l(()=>[...e[8]||(e[8]=[r("Moshe Zadka",-1)])]),_:1}),e[13]||(e[13]=r(" 選題：",-1)),i(a,{href:"https://github.com/lujun9972"},{default:l(()=>[...e[9]||(e[9]=[r("lujun9972",-1)])]),_:1}),e[14]||(e[14]=r(" 譯者：",-1)),i(a,{href:"https://github.com/Yufei-Yan"},{default:l(()=>[...e[10]||(e[10]=[r("MCGA",-1)])]),_:1}),e[15]||(e[15]=r(" 校對：",-1)),i(a,{href:"https://github.com/wxy"},{default:l(()=>[...e[11]||(e[11]=[r("wxy",-1)])]),_:1})]),t("p",null,[e[18]||(e[18]=r("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...e[16]||(e[16]=[r("LCTT",-1)])]),_:1}),e[19]||(e[19]=r(" 原創編譯，",-1)),i(a,{href:"https://linux.cn/"},{default:l(()=>[...e[17]||(e[17]=[r("Linux中國",-1)])]),_:1}),e[20]||(e[20]=r(" 榮譽推出",-1))])])}const x=n(d,[["render",u]]);export{c as __pageData,x as default};
